#!/usr/bin/env python3
"""Unified data loader for 15-model cert_manip_resist_eval pipeline.

Handles two data formats:
  - Checkpoint files (local 6 models): nested {clean_scores: {ds: {model: [...]}}}
  - Individual JSON files (API 9 models): flat {scores: [...], asr, accuracy, ...}
"""

import json
import logging
from pathlib import Path

logger = logging.getLogger(__name__)

# ── Model lists ──────────────────────────────────────────────────────
LOCAL_MODELS = [
    "qwen2.5-72b", "llama3.1-70b", "mistral-large",
    "qwen2.5-32b", "qwen2.5-14b", "llama3.1-8b",
]
API_MODELS = [
    "claude-opus-4", "gpt-5.5", "gemini-2.5-pro", "gpt-4.1",
    "claude-sonnet-4", "gpt-4o", "gemini-2.5-flash",
    "gpt-4o-mini", "claude-3-haiku",
]
ALL_MODELS = LOCAL_MODELS + API_MODELS
DATASETS = ["mmlu", "arc_challenge"]
ATTACKS = [
    "prompt_injection", "sycophancy", "score_manipulation",
    "verbosity_bias", "position_bias", "authority_bias",
]

# ── Default paths ────────────────────────────────────────────────────
RESULTS_DIR = Path("/root/cert_manip_resist_eval/artifacts/results")
PLAN001_DIR = RESULTS_DIR / "plan001"
SCORES_DIR = PLAN001_DIR / "individual_scores"
MI_PATH = PLAN001_DIR / "mi_matrix" / "mi_matrix_15models.json"
CKPT_FILES = [
    RESULTS_DIR / "_taxonomy_checkpoint.json",
    RESULTS_DIR / "_step2v3_checkpoint.json",
]
OUTPUT_DIR = PLAN001_DIR / "panel_regression"


def _invert_winners(scores):
    swap = {"A": "B", "B": "A", "tie": "tie"}
    return [{**s, "winner": swap.get(s.get("winner", "tie"), "tie")} for s in scores]


def load_all_scores(
    checkpoint_files=None,
    individual_dir=None,
    datasets=None,
    attacks=None,
    all_models=None,
):
    """Load sample-level clean + attacked scores for all 15 models.

    Returns:
        clean:    {ds: {model_id: [score_dicts]}}
        attacked: {ds: {atk: {model_id: [score_dicts]}}}
    """
    checkpoint_files = checkpoint_files or CKPT_FILES
    individual_dir = Path(individual_dir or SCORES_DIR)
    datasets = datasets or DATASETS
    attacks = attacks or ATTACKS
    all_models = all_models or ALL_MODELS

    clean = {ds: {} for ds in datasets}
    attacked = {ds: {a: {} for a in attacks} for ds in datasets}

    for ckpt_path in checkpoint_files:
        ckpt_path = Path(ckpt_path)
        if not ckpt_path.exists():
            logger.warning(f"Checkpoint not found: {ckpt_path}")
            continue
        logger.info(f"Loading checkpoint: {ckpt_path.name}")
        with open(ckpt_path) as f:
            data = json.load(f)
        for ds in datasets:
            for mid, scores in data.get("clean_scores", {}).get(ds, {}).items():
                if mid not in clean[ds]:
                    clean[ds][mid] = scores
            for atk in attacks:
                for mid, scores in (
                    data.get("attacked_scores", {}).get(ds, {}).get(atk, {}).items()
                ):
                    if mid not in attacked[ds][atk]:
                        if atk == "position_bias":
                            scores = _invert_winners(scores)
                        attacked[ds][atk][mid] = scores

    if individual_dir.exists():
        logger.info(f"Loading individual scores from {individual_dir}")
        for mid in all_models:
            for ds in datasets:
                fp = individual_dir / f"{mid}__{ds}__clean.json"
                if fp.exists() and mid not in clean[ds]:
                    with open(fp) as f:
                        clean[ds][mid] = json.load(f).get("scores", [])
                for atk in attacks:
                    fp = individual_dir / f"{mid}__{ds}__{atk}.json"
                    if fp.exists() and mid not in attacked[ds][atk]:
                        with open(fp) as f:
                            scores = json.load(f).get("scores", [])
                        if atk == "position_bias":
                            scores = _invert_winners(scores)
                        attacked[ds][atk][mid] = scores

    for ds in datasets:
        nc = len(clean[ds])
        logger.info(f"  {ds} clean: {nc}/{len(all_models)}")
        for atk in attacks:
            na = len(attacked[ds][atk])
            if na > 0:
                logger.info(f"  {ds} {atk}: {na}/{len(all_models)}")

    return clean, attacked


def load_pairs(checkpoint_files=None, datasets=None):
    """Load evaluation pairs from checkpoint files.

    Returns: {ds: [pair_dicts]} with up to 300 pairs per dataset.
    """
    checkpoint_files = checkpoint_files or CKPT_FILES
    datasets = datasets or DATASETS

    for ckpt_path in checkpoint_files:
        ckpt_path = Path(ckpt_path)
        if not ckpt_path.exists():
            continue
        with open(ckpt_path) as f:
            data = json.load(f)
        if "pairs" not in data:
            continue
        pairs = {}
        for ds in datasets:
            if ds in data["pairs"]:
                pairs[ds] = data["pairs"][ds][:300]
                logger.info(f"  Pairs {ds}: {len(pairs[ds])} from {ckpt_path.name}")
        if pairs:
            return pairs
    raise FileNotFoundError("No pairs found in any checkpoint file")


def load_mi_data(mi_path=None):
    """Load MI matrix from Step 3 output."""
    mi_path = Path(mi_path or MI_PATH)
    if not mi_path.exists():
        raise FileNotFoundError(
            f"MI matrix not found: {mi_path}. Run Step 3 first."
        )
    with open(mi_path) as f:
        data = json.load(f)
    logger.info(f"Loaded MI matrix: {len(data['models'])} models")
    return data


def load_api_asr(individual_dir=None, datasets=None, attacks=None, api_models=None):
    """Load pre-computed ASR for API models from individual score files.

    Returns: {ds: {atk: {model_id: asr}}}
    """
    individual_dir = Path(individual_dir or SCORES_DIR)
    datasets = datasets or DATASETS
    attacks = attacks or ATTACKS
    api_models = api_models or API_MODELS

    asr_data = {}
    for model_id in api_models:
        for ds in datasets:
            if ds not in asr_data:
                asr_data[ds] = {}
            clean_path = individual_dir / f"{model_id}__{ds}__clean.json"
            if not clean_path.exists():
                continue
            for atk in attacks:
                if atk not in asr_data[ds]:
                    asr_data[ds][atk] = {}
                atk_path = individual_dir / f"{model_id}__{ds}__{atk}.json"
                if not atk_path.exists():
                    continue
                with open(atk_path) as f:
                    atk_data = json.load(f)
                asr = atk_data.get("asr")
                if asr is not None:
                    asr_data[ds][atk][model_id] = asr
    return asr_data


def validate_coverage(clean, attacked, datasets=None, attacks=None,
                      all_models=None, expected_samples=300):
    """Check that all models have expected number of samples. Returns list of issues."""
    datasets = datasets or DATASETS
    attacks = attacks or ATTACKS
    all_models = all_models or ALL_MODELS

    issues = []
    for ds in datasets:
        for mid in all_models:
            if mid not in clean[ds]:
                issues.append(f"MISSING clean: {ds}/{mid}")
            elif len(clean[ds][mid]) != expected_samples:
                issues.append(
                    f"COUNT clean: {ds}/{mid} has {len(clean[ds][mid])}, "
                    f"expected {expected_samples}"
                )
            for atk in attacks:
                if mid not in attacked[ds][atk]:
                    issues.append(f"MISSING attacked: {ds}/{atk}/{mid}")
                elif len(attacked[ds][atk][mid]) != expected_samples:
                    issues.append(
                        f"COUNT attacked: {ds}/{atk}/{mid} has "
                        f"{len(attacked[ds][atk][mid])}, expected {expected_samples}"
                    )
    if issues:
        logger.warning(f"Validation: {len(issues)} issues")
        for i in issues[:20]:
            logger.warning(f"  {i}")
        if len(issues) > 20:
            logger.warning(f"  ... and {len(issues) - 20} more")
    else:
        logger.info(
            f"Validation passed: {len(all_models)} models x "
            f"{len(datasets)} datasets x {len(attacks)+1} conditions"
        )
    return issues

#!/usr/bin/env python3
"""Plan 001 Step 3: Compute 15-model pairwise MI matrix and K_eff for all C(15,3) panels."""

import os
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"

import sys
sys.path.insert(0, "/root/cert_manip_resist_eval")

import json
import itertools
import numpy as np
from pathlib import Path
from sklearn.metrics import mutual_info_score

from src.utils import setup_logging
from src.unified_data_loader import (
    ALL_MODELS, DATASETS, PLAN001_DIR, load_all_scores,
)

logger = setup_logging("plan001_step3_mi")

MI_DIR = PLAN001_DIR / "mi_matrix"


def extract_winner_vector(score_list):
    winners = []
    for s in score_list:
        w = s.get("winner", "tie") if isinstance(s, dict) else "tie"
        winners.append(w)
    return winners


def compute_pairwise_mi(winners_i, winners_j):
    n = min(len(winners_i), len(winners_j))
    if n == 0:
        return 0.0
    return mutual_info_score(winners_i[:n], winners_j[:n])


def build_mi_matrix(clean_scores, dataset):
    ds_scores = clean_scores.get(dataset, {})
    n_models = len(ALL_MODELS)
    mi_mat = np.zeros((n_models, n_models))

    winner_vectors = {}
    for i, model_id in enumerate(ALL_MODELS):
        if model_id in ds_scores:
            winner_vectors[i] = extract_winner_vector(ds_scores[model_id])
        else:
            logger.warning(f"No clean scores for {model_id} on {dataset}")

    for i in range(n_models):
        for j in range(i + 1, n_models):
            if i in winner_vectors and j in winner_vectors:
                mi = compute_pairwise_mi(winner_vectors[i], winner_vectors[j])
                mi_mat[i, j] = mi
                mi_mat[j, i] = mi

    return mi_mat


def mi_based_keff(mi_matrix, model_indices):
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix[i_idx, j_idx])
        keff += term
    return keff / K


def compute_all_panel_keffs(mi_matrix, dataset):
    n_models = len(ALL_MODELS)
    idx_to_model = {i: m for i, m in enumerate(ALL_MODELS)}
    panels = {}

    for combo in itertools.combinations(range(n_models), 3):
        model_ids = [idx_to_model[i] for i in combo]
        panel_key = "|".join(model_ids)
        keff = mi_based_keff(mi_matrix, list(combo))

        mi_pairs = {}
        for a, b in itertools.combinations(combo, 2):
            pair_key = f"{idx_to_model[a]}|{idx_to_model[b]}"
            mi_pairs[pair_key] = float(mi_matrix[a, b])

        panels[panel_key] = {
            "models": model_ids,
            "keff": float(keff),
            "mi_pairs": mi_pairs,
        }

    return panels


def main():
    logger.info("=== Plan 001 Step 3: MI Matrix Computation ===")

    clean_scores, _ = load_all_scores()

    for ds in DATASETS:
        available = list(clean_scores.get(ds, {}).keys())
        missing = [m for m in ALL_MODELS if m not in available]
        logger.info(f"  {ds}: {len(available)}/{len(ALL_MODELS)} models available")
        if missing:
            logger.warning(f"  {ds}: missing models: {missing}")

    available_count = sum(
        1 for ds in DATASETS
        for m in ALL_MODELS
        if m in clean_scores.get(ds, {})
    )
    total_needed = len(DATASETS) * len(ALL_MODELS)
    if available_count < total_needed:
        logger.warning(
            f"Only {available_count}/{total_needed} model*dataset combos available. "
            f"MI matrix will have zeros for missing pairs."
        )

    mi_matrices = {}
    keff_per_panel = {}

    for ds in DATASETS:
        logger.info(f"\n--- Computing MI matrix for {ds} ---")
        mi_mat = build_mi_matrix(clean_scores, ds)
        mi_matrices[ds] = mi_mat.tolist()

        nonzero = np.count_nonzero(mi_mat)
        max_possible = len(ALL_MODELS) * (len(ALL_MODELS) - 1)
        logger.info(f"  MI matrix: {nonzero}/{max_possible} non-zero entries")
        if nonzero > 0:
            upper = mi_mat[np.triu_indices_from(mi_mat, k=1)]
            upper_nz = upper[upper > 0]
            if len(upper_nz) > 0:
                logger.info(
                    f"  MI range: [{upper_nz.min():.4f}, {upper_nz.max():.4f}], "
                    f"mean={upper_nz.mean():.4f}"
                )

        logger.info(f"  Computing K_eff for all C(15,3)=455 panels on {ds}...")
        panels = compute_all_panel_keffs(mi_mat, ds)
        keff_per_panel[ds] = panels

        keff_values = [p["keff"] for p in panels.values()]
        logger.info(
            f"  K_eff range: [{min(keff_values):.3f}, {max(keff_values):.3f}], "
            f"mean={np.mean(keff_values):.3f}"
        )

    MI_DIR.mkdir(parents=True, exist_ok=True)
    output = {
        "models": ALL_MODELS,
        "mi_matrix": mi_matrices,
        "keff_per_panel": keff_per_panel,
    }
    output_path = MI_DIR / "mi_matrix_15models.json"
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)
    logger.info(f"\nSaved MI matrix to {output_path}")

    print("\n" + "=" * 70)
    print("MI MATRIX SUMMARY")
    print("=" * 70)
    for ds in DATASETS:
        mi_mat = np.array(mi_matrices[ds])
        upper = mi_mat[np.triu_indices_from(mi_mat, k=1)]
        n_computed = np.count_nonzero(upper)
        print(f"\n{ds}:")
        print(f"  Pairwise MI computed: {n_computed}/105")
        if n_computed > 0:
            nz = upper[upper > 0]
            print(f"  MI range: [{nz.min():.4f}, {nz.max():.4f}]")
            print(f"  MI mean:  {nz.mean():.4f}")
        keffs = [p["keff"] for p in keff_per_panel[ds].values()]
        print(f"  K_eff (455 panels): [{min(keffs):.3f}, {max(keffs):.3f}], mean={np.mean(keffs):.3f}")
    print("=" * 70)


if __name__ == "__main__":
    main()
